def caesar(s, shift):
    """
    Shifts each letter in the string s by the specified number of places.
    Wraps around if necessary, preserving case.

    :param s: The string to be shifted.
    :param shift: The number of positions to shift each letter.
    :return: A new string with each letter shifted according to the shift.
    """
    def shift_char(c):
        if c.islower():
            return chr((ord(c) - ord('a') + shift) % 26 + ord('a'))
        elif c.isupper():
            return chr((ord(c) - ord('A') + shift) % 26 + ord('A'))
        else:
            return c

    return ''.join(shift_char(c) for c in s)

