def transpose(m):
    if not m:
        return []

    # Initialize the result matrix with zeros
    result = [[0 for _ in range(len(m[0]))] for _ in range(len(m))]

    # Iterate over each row and column of the input matrix
    for i in range(len(m)):
        for j in range(len(m[0])):
            # Place the element from the current row and column into the corresponding position in the result matrix
            result[j][i] = m[i][j]

    return result
