def dedupe_count(nums):
    """
    Given a list of numbers, return a dictionary where the keys are unique numbers and the values are their counts.

    Example:
    >>> dedupe_count([1, 2, 3, 2, 4])
    {1: 1, 2: 2, 3: 1, 4: 1}
    """
    count_dict = {}
    for num in nums:
        if num in count_dict:
            count_dict[num] += 1
        else:
            count_dict[num] = 1
    return count_dict
```

