def count_primes(limit):
    """
    Count the number of prime numbers less than the given limit.

    Args:
    limit (int): The upper limit (exclusive) to check for prime numbers.

    Returns:
    int: The count of prime numbers less than the limit.
    """
    if limit < 2:
        return 0

    def is_prime(num):
        """Check if a number is prime."""
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    count = 0
    for num in range(2, limit):
        if is_prime(num):
            count += 1
    return count
