    char_count = {}

    # Count occurrences of each character in the string
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the first character with a count of 1
    for i, char in enumerate(s):
        if char_count[char] == 1:
