def two_sum_closest(nums, target):
    nums.sort()
    closest_pair = (nums[0], nums[-1])
    min_diff = abs(target - closest_pair[0] - closest_pair[1])

    for i in range(len(nums) - 1):
        left, right = i + 1, len(nums) - 1
        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]
            diff = abs(current_sum - target)
            if diff < min_diff:
                min_diff = diff
                closest_pair = (nums[i], nums[left], nums[right])
            if current_sum > target:
                right -= 1
            else:
                left += 1

    return closest_pair
```

